    public class GEUsingHistoryController : BaseBusinessController
    {
        public GEUsingHistoryController()
        {
            dal = new DALBaseProvider("GEUsingHistory", typeof(GEUsingHistoryInfo));
        }
        public List<GEUsingHistoryInfo> GetHistoryList(string user, DateTime from, DateTime to)
        {
            DataSet ds = dal.GetDataSet("GEUsingHistory_GetUsingHistoryList", user, from, to);
            List<GEUsingHistoryInfo> result = new List<GEUsingHistoryInfo>();

            if (ds.Tables.Count != 0 && ds.Tables[0].Rows.Count != 0)
            {
                foreach (DataRow row in ds.Tables[0].Rows)
                {
                    GEUsingHistoryInfo objHistory = GetObjectFromDataRow(row) as GEUsingHistoryInfo;
                    result.Add(objHistory);
                }
            }

            return result;
        }

        public bool CheckUserLogged(int ADUserID)
        {
            String query = String.Format("select count(*) from GEUsingHistory where ADUserID = {0} and GEUsingHistoryType = 'LogIn'", ADUserID);
            int iCount = 0;
            System.Data.Common.DbCommand cmd = SqlDatabaseHelper.GetQuery(query);
            DataSet ds = SqlDatabaseHelper.RunQuery(cmd);
            if (ds.Tables.Count > 0)
            {
                if (ds.Tables[0].Rows.Count > 0)
                {
                    iCount = Convert.ToInt32(ds.Tables[0].Rows[0][0]);
                }
            }
            if (iCount > 0)
                return true;
            return false;
        }
    }
